	var s Supervisor
	var mu sync.Mutex
	finished := false

	started := make(chan struct{})
	s.Start(context.Background(), nil, func(ctx context.Context) error {
		close(started)
		<-ctx.Done()
		time.Sleep(50 * time.Millisecond) // unwinding after cancellation
		mu.Lock()
		finished = true
		mu.Unlock()
		return ctx.Err()
	})
	<-started

	stopCtx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	s.Stop(stopCtx, nil)

	mu.Lock()
	defer mu.Unlock()
	if !finished {
		t.Error("Stop() returned before the seed finished unwinding")
	}
}","class":"http://www.ontologyrepository.com/CommonCoreOntologies/Algorithm","handle":"c360.semsource-d0da92.workspace.golang.function.internal-seedsup-supervisor_test-go-TestStopWaitsForTheSeed"},{"name":"DecisionTypeRefactor","kind":"const","path":"source/vocabulary/git.go","lines":[59,59],"body":"	DecisionTypeRefactor DecisionTypeValue = "refactor"","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-d0da92.workspace.golang.const.source-vocabulary-git-go-DecisionTypeRefactor"},{"name":"readySemantic","kind":"const","path":"ui/e2e/workbench.spec.ts","lines":[389,389],"body":"  const readySemantic = structuredClone(capabilities);","class":"http://www.ontologyrepository.com/CommonCoreOntologies/SoftwareCode","handle":"c360.semsource-d0da92.workspace.typescript.const.ui-e2e-workbench-spec-ts-readySemantic"},{"name":"incrementErrors","kind":"method","path":"processor/ast-source/component.go","lines":[887,889],"body":"func (c *Component) incrementErrors() {
